import * as THREE from './vendor/three.module.js';
export function createCarFire(parent){
 const group=new THREE.Group();group.name='Incendio del Tesla ALBERTO';group.visible=false;parent.add(group);const textures=[],materials=[];
 function texture(smoke){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,0,32,32,32);gradient.addColorStop(0,smoke?'rgba(29,27,25,.8)':'rgba(255,246,173,1)');gradient.addColorStop(.3,smoke?'rgba(42,39,35,.55)':'rgba(255,157,26,.92)');gradient.addColorStop(.7,smoke?'rgba(51,47,42,.22)':'rgba(209,41,5,.3)');gradient.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);const map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;textures.push(map);return map;}
 const flame=texture(false),smoke=texture(true),particles=[];for(let i=0;i<32;i++){const isSmoke=i>=16;const material=new THREE.SpriteMaterial({map:isSmoke?smoke:flame,transparent:true,depthWrite:false,blending:isSmoke?THREE.NormalBlending:THREE.AdditiveBlending});materials.push(material);const sprite=new THREE.Sprite(material);group.add(sprite);particles.push({sprite,smoke:isSmoke,seed:i*2.39996});}
 const light=new THREE.PointLight('#ff7a20',8,13,2);light.position.set(0,1,2.7);group.add(light);
 return {update(time){group.visible=time!==null;if(time===null)return;const blast=Math.exp(-(((time-.45)/.2)**2));light.intensity=5+blast*30+Math.sin(time*18)*1.5;for(const {sprite,smoke,seed} of particles){const life=((time*(smoke?.22:1.25)+seed)%1+1)%1;const size=smoke?1+life*3.2:(1-life)*(.8+blast*2)+.15;sprite.position.set(Math.sin(seed*6.3)*(smoke?.7+life:.72),smoke?1.2+life*5.5:.35+life*2.5,2.6+Math.cos(seed*2.1)*.32);sprite.scale.set(size,size*(smoke?1:1.65),1);sprite.material.opacity=(1-life)*(smoke?.72:.94);}},dispose(){for(const m of materials)m.dispose();for(const t of textures)t.dispose();group.removeFromParent();}};
}
